using System;using System.Reflection;using System.Runtime.Serialization;
class SidewalkRepeatChecks237
{
 static int n;static void Check(bool value,string why){n++;if(!value)throw new Exception(why);}
 static void Main(){var a=Assembly.LoadFrom("MedianGrassReplacement.dll");var flags=BindingFlags.NonPublic|BindingFlags.Static;var p=a.GetType("MedianGrassReplacement.Systems.SidewalkRepeatPolicy",true);var repeats=p.GetMethod("Repeats",flags);var needs=p.GetMethod("NeedsBake",flags);foreach(float input in new[]{float.NaN,float.PositiveInfinity,float.NegativeInfinity,-100f,0f,.1f,.9f,1f,1.49f,1.5f,2f,5.6f,9.9f,10f,100f}){int actual=(int)repeats.Invoke(null,new object[]{input});int expected=float.IsNaN(input)||float.IsInfinity(input)?1:(int)Math.Floor(Math.Max(1,Math.Min(10,input))+.5f);Check(actual==expected&&actual>=1&&actual<=10,"Repeat migration/clamping failed");}
 foreach(var shader in new[]{"BH/NetCompositionMeshLitShader","BH/AreaDecalShader","other",null})for(int role=0;role<=5;role++)Check((bool)needs.Invoke(null,new object[]{shader,role})==(shader=="BH/NetCompositionMeshLitShader"&&role==2),"Repeat scope broadened beyond owned native sidewalk colour map");
 var st=a.GetType("MedianGrassReplacement.Setting",true);var settings=FormatterServices.GetUninitializedObject(st);st.GetMethod("SetSurfaceDefaults",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(settings,null);var property=st.GetProperty("SidewalkSurfaceTiling");float road=(float)st.GetProperty("RoadSurfaceUv").GetValue(settings);for(int i=1;i<=10;i++){property.SetValue(settings,(float)i);Check((float)property.GetValue(settings)==i,"Settings lost an integer repeat");Check((float)st.GetProperty("RoadSurfaceUv").GetValue(settings)==road,"Sidewalk slider changed road scale");}
 for(int repeatsCount=1;repeatsCount<=10;repeatsCount++)for(int i=0;i<100;i++){double u=i/100d;double f=u*repeatsCount-Math.Floor(u*repeatsCount),g=(u+1)*repeatsCount-Math.Floor((u+1)*repeatsCount);Check(Math.Abs(f-g)<1e-10,"Whole repeat is not periodic at a native UV boundary");}
 Console.WriteLine("PASS: "+n+" integer-repeat, legacy value, material-scope, independent-settings and periodic-UV checks. GPU helper is tested separately in Unity; no city or native save executed.");}
}
